WITH recent_web_events AS (SELECT * FROM web_events WHERE (session_id IN (11, 17, 23, 28) AND event_type IN ('page_view', 'search')) OR HOUR(event_time) BETWEEN 7 AND 13), Agg AS (SELECT page, COUNT(CASE WHEN event_type = 'add_to_cart' THEN 1 END) AS add_to_cart_count FROM recent_web_events GROUP BY page) SELECT page, add_to_cart_count FROM Agg WHERE add_to_cart_count >= 10 ORDER BY add_to_cart_count DESC
